@'
import test from "node:test";
import assert from "node:assert/strict";
import { buildShipmentGroups, calculateOrderTotal, isBatchOrderable } from "../src/commerce.mjs";

const items = [
  { productId: "label-1", name: "Label", kind: "on_hand", quantity: 2, price: 300, stock: 8 },
  { productId: "printer-1", name: "Printer", kind: "on_hand", quantity: 1, price: 1700, stock: 1 },
  { productId: "gb-1", name: "Group item A", kind: "group_buy", batchId: "batch-a", quantity: 1, price: 500 },
  { productId: "gb-2", name: "Group item B", kind: "group_buy", batchId: "batch-a", quantity: 3, price: 250 },
  { productId: "gb-3", name: "Group item C", kind: "group_buy", batchId: "batch-b", quantity: 2, price: 900 },
];

test("combined shipping creates one shipment for all cart lines", () => {
  const groups = buildShipmentGroups(items, "together");
  assert.equal(groups.length, 1);
  assert.equal(groups[0].quantity, 9);
  assert.equal(groups[0].lines.length, 5);
});

test("separate shipping groups on-hand lines and each buy batch", () => {
  const groups = buildShipmentGroups(items, "separate");
  assert.deepEqual(groups.map((group) => [group.kind, group.batchId, group.quantity]), [
    ["on_hand", null, 3],
    ["group_buy", "batch-a", 4],
    ["group_buy", "batch-b", 2],
  ]);
});

test("order totals use one shipping rate per shipment group", () => {
  const total = calculateOrderTotal(items, "separate", (quantity) => quantity === 3 ? 100 : 150);
  assert.equal(total.subtotal, 5650);
  assert.equal(total.shipping, 400);
  assert.equal(total.total, 6050);
});

test("batch closes at deadline and closed status", () => {
  const now = new Date("2026-10-28T12:00:00.000Z");
  assert.equal(isBatchOrderable({ status: "open", deadline: "2026-10-28T12:01:00.000Z" }, now), true);
  assert.equal(isBatchOrderable({ status: "open", deadline: "2026-10-28T11:59:00.000Z" }, now), false);
  assert.equal(isBatchOrderable({ status: "closed", deadline: "2026-10-29T12:00:00.000Z" }, now), false);
});
