@'
import test from "node:test";
import assert from "node:assert/strict";
import { prepareGroupBuyOrder } from "./commerce";

const products = new Map([
  ["label", { id: "label", name: "Label", fullName: "Laser Label", kind: "on_hand", price: 300, stock: 3, isAvailable: true, batchId: null }],
  ["gb-a", { id: "gb-a", name: "Tea A", fullName: "Tea A", kind: "group_buy", price: 500, stock: 0, isAvailable: true, batchId: 10 }],
]);
const batches = new Map([[10, { id: 10, status: "open", deadline: "2026-10-29T12:00:00.000Z" }]]);
const shippingConfig = {
  luzon: { "1": 80, "2": 100, max: 120 },
  visayas: { "1": 90, "2": 120, max: 150 },
};
const now = new Date("2026-10-28T12:00:00.000Z");

test("uses database prices and calculates one area rate per shipment", () => {
  const order = prepareGroupBuyOrder({
    items: [{ productId: "label", quantity: 2, price: 1 }],
    shipmentPreference: "separate",
    region: "luzon",
    shippingConfig,
    products,
    batches,
    now,
  });
  assert.equal(order.subtotal, 60000);
  assert.equal(order.shippingFee, 10000);
  assert.equal(order.total, 70000);
  assert.equal(order.items[0].unitPrice, 30000);
});

test("separate shipping produces an on-hand shipment and a shipment per batch", () => {
  const order = prepareGroupBuyOrder({
    items: [
      { productId: "label", quantity: 1 },
      { productId: "gb-a", quantity: 2 },
    ],
    shipmentPreference: "separate",
    region: "luzon",
    shippingConfig,
    products,
    batches,
    now,
  });
  assert.deepEqual(order.shipments.map((shipment) => [shipment.kind, shipment.batchId, shipment.shippingFee]), [
    ["on_hand", null, 8000],
    ["group_buy", 10, 10000],
  ]);
});

test("rejects unavailable stock and expired batches", () => {
  assert.throws(() => prepareGroupBuyOrder({
    items: [{ productId: "label", quantity: 4 }],
    shipmentPreference: "together", region: "luzon", shippingConfig, products, batches, now,
  }), /not enough stock/i);
  assert.throws(() => prepareGroupBuyOrder({
    items: [{ productId: "gb-a", quantity: 1 }],
    shipmentPreference: "together", region: "luzon", shippingConfig, products,
    batches: new Map([[10, { id: 10, status: "open", deadline: "2026-10-28T11:00:00.000Z" }]]), now,
  }), /batch is closed/i);
});
