*** Add File: ../admin-pbc/lib/group-buy/commerce.ts
+export type GroupBuyItemInput = { productId: string; quantity: number };
+
+type CommerceProduct = {
+  id: string;
+  name: string;
+  fullName: string;
+  storefrontKey: string;
+  kind: "standard" | "on_hand" | "group_buy";
+  price: number;
+  stock: number;
+  isAvailable: boolean | null;
+  batchId: number | null;
+};
+
+type CommerceBatch = {
+  id: number;
+  status: string;
+  deadline: string | Date;
+};
+
+type ShippingRates = Record<string, Record<string, number>>;
+
+function isOrderable(batch: CommerceBatch | undefined, now: Date) {
+  return Boolean(
+    batch &&
+      batch.status === "open" &&
+      new Date(batch.deadline).getTime() > now.getTime()
+  );
+}
+
+function getShippingRate(config: ShippingRates, region: string, quantity: number) {
+  const normalized = region.trim().toLowerCase();
+  let rates = config[normalized];
+  if (!rates) {
+    if (normalized.includes("luzon")) rates = config.luzon;
+    else if (normalized.includes("visaya")) rates = config.visayas;
+    else if (normalized.includes("mindanao")) rates = config.mindanao;
+    else rates = config.other;
+  }
+  if (!rates) throw new Error("Shipping is unavailable for this region.");
+  return quantity <= 1 ? rates["1"] ?? 0 : quantity === 2 ? rates["2"] ?? 0 : rates.max ?? 0;
+}
+
+export function prepareGroupBuyOrder(input: {
+  items: Array<GroupBuyItemInput & { price?: number }>;
+  shipmentPreference: "together" | "separate";
+  region: string;
+  shippingConfig: ShippingRates;
+  products: Map<string, CommerceProduct>;
+  batches: Map<number, CommerceBatch>;
+  now?: Date;
+}) {
+  if (!input.items.length) throw new Error("Cart is empty.");
+
+  const quantities = new Map<string, number>();
+  for (const item of input.items) {
+    const quantity = Number(item.quantity);
+    if (!item.productId || !Number.isInteger(quantity) || quantity < 1 || quantity > 100) {
+      throw new Error("Invalid cart item.");
+    }
+    quantities.set(item.productId, (quantities.get(item.productId) ?? 0) + quantity);
+  }
+
+  const now = input.now ?? new Date();
+  const orderItems = [...quantities].map(([productId, quantity]) => {
+    const product = input.products.get(productId);
+    if (
+      !product ||
+      product.storefrontKey !== "tindahan" ||
+      product.kind === "standard" ||
+      !product.isAvailable
+    ) {
+      throw new Error("A product is no longer available. Refresh the catalog and try again.");
+    }
+    if (product.kind === "on_hand" && product.stock < quantity) {
+      throw new Error(`Not enough stock for ${product.name}.`);
+    }
+    if (product.kind === "group_buy" && !isOrderable(product.batchId ? input.batches.get(product.batchId) : undefined, now)) {
+      throw new Error(`The group-buy batch for ${product.name} is closed.`);
+    }
+    const unitPrice = Math.round(product.price * 100);
+    return {
+      productId: product.id,
+      productName: product.fullName,
+      productKind: product.kind,
+      batchId: product.batchId,
+      unitPrice,
+      quantity,
+      subtotal: unitPrice * quantity,
+    };
+  });
+
+  const groups: Array<{ kind: "combined" | "on_hand" | "group_buy"; batchId: number | null; itemIndexes: number[]; quantity: number }> = [];
+  if (input.shipmentPreference === "together") {
+    groups.push({
+      kind: "combined",
+      batchId: null,
+      itemIndexes: orderItems.map((_, index) => index),
+      quantity: orderItems.reduce((sum, item) => sum + item.quantity, 0),
+    });
+  } else {
+    const groupMap = new Map<string, (typeof groups)[number]>();
+    orderItems.forEach((item, index) => {
+      const kind = item.productKind === "on_hand" ? "on_hand" : "group_buy";
+      const key = kind === "on_hand" ? "on_hand" : `batch:${item.batchId}`;
+      const group = groupMap.get(key) ?? {
+        kind,
+        batchId: kind === "group_buy" ? item.batchId : null,
+        itemIndexes: [],
+        quantity: 0,
+      };
+      group.itemIndexes.push(index);
+      group.quantity += item.quantity;
+      groupMap.set(key, group);
+    });
+    groups.push(...groupMap.values());
+  }
+
+  const shipments = groups.map((group) => ({
+    ...group,
+    shippingFee: Math.round(getShippingRate(input.shippingConfig, input.region, group.quantity) * 100),
+  }));
+  const subtotal = orderItems.reduce((sum, item) => sum + item.subtotal, 0);
+  const shippingFee = shipments.reduce((sum, shipment) => sum + shipment.shippingFee, 0);
+  return {
+    items: orderItems.map((item, itemIndex) => ({
+      ...item,
+      shipmentIndex: shipments.findIndex((shipment) => shipment.itemIndexes.includes(itemIndex)),
+    })),
+    shipments,
+    subtotal,
+    shippingFee,
+    total: subtotal + shippingFee,
+  };
+}
*** End Patch";
