import { eq } from "drizzle-orm";
import { google } from "googleapis";
import { Readable } from "node:stream";
import { db } from "@/lib/db";
import { appSettings } from "@/lib/db/schema";
import { decryptGoogleDriveRefreshToken, encryptGoogleDriveRefreshToken } from "@/lib/google-drive/oauth-crypto";

export const TINDAHAN_DRIVE_FILE_SCOPE = "https://www.googleapis.com/auth/drive.file";
const settingKey = "tindahan_group_buy_drive";
const folderMimeType = "application/vnd.google-apps.folder";

type DriveSettings = {
  encryptedRefreshToken?: string;
  folderId?: string;
  folderName?: string;
};

function createSettingsValue(value: unknown): DriveSettings {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  const stored = value as Record<string, unknown>;
  return {
    ...(typeof stored.encryptedRefreshToken === "string" ? { encryptedRefreshToken: stored.encryptedRefreshToken } : {}),
    ...(typeof stored.folderId === "string" ? { folderId: stored.folderId } : {}),
    ...(typeof stored.folderName === "string" ? { folderName: stored.folderName } : {}),
  };
}

async function readSettings() {
  const setting = await db.query.appSettings.findFirst({ where: eq(appSettings.key, settingKey) });
  return createSettingsValue(setting?.value);
}

async function saveSettings(patch: Partial<DriveSettings>) {
  const value = { ...(await readSettings()), ...patch };
  await db.insert(appSettings).values({ key: settingKey, value }).onConflictDoUpdate({
    target: appSettings.key,
    set: { value, updatedAt: new Date() },
  });
}

export function createTindahanDriveOAuthClient(redirectUri?: string) {
  const clientId = process.env.GOOGLE_OAUTH_CLIENT_ID;
  const clientSecret = process.env.GOOGLE_OAUTH_CLIENT_SECRET;
  if (!clientId || !clientSecret) throw new Error("Google Drive OAuth is not configured.");
  return new google.auth.OAuth2(clientId, clientSecret, redirectUri);
}

export async function saveTindahanDriveRefreshToken(refreshToken: string) {
  await saveSettings({ encryptedRefreshToken: encryptGoogleDriveRefreshToken(refreshToken) });
}

export async function getTindahanGroupBuyDriveStatus() {
  const settings = await readSettings();
  return {
    connected: Boolean(settings.encryptedRefreshToken),
    folderName: settings.folderName ?? null,
  };
}

async function getTindahanDriveClient() {
  const settings = await readSettings();
  if (!settings.encryptedRefreshToken) throw new Error("Group-buy receipt storage is not connected.");
  const client = createTindahanDriveOAuthClient();
  client.setCredentials({ refresh_token: decryptGoogleDriveRefreshToken(settings.encryptedRefreshToken) });
  return google.drive({ version: "v3", auth: client });
}

export async function getTindahanDrivePickerAccessToken() {
  const settings = await readSettings();
  if (!settings.encryptedRefreshToken) throw new Error("Group-buy receipt storage is not connected.");
  const client = createTindahanDriveOAuthClient();
  client.setCredentials({ refresh_token: decryptGoogleDriveRefreshToken(settings.encryptedRefreshToken) });
  const result = await client.getAccessToken();
  if (!result.token) throw new Error("Google Drive could not provide an access token.");
  return result.token;
}

export async function saveTindahanGroupBuyReceiptFolder(folderId: string) {
  if (!/^[A-Za-z0-9_-]{5,256}$/.test(folderId)) throw new Error("Choose a valid Google Drive folder.");
  const drive = await getTindahanDriveClient();
  const result = await drive.files.get({ fileId: folderId, fields: "id,name,mimeType" });
  if (result.data.mimeType !== folderMimeType || !result.data.id || !result.data.name) {
    throw new Error("Choose a Google Drive folder for group-buy receipts.");
  }
  await saveSettings({ folderId: result.data.id, folderName: result.data.name });
  return result.data.name;
}

export async function uploadTindahanGroupBuyPaymentProof(buffer: Buffer, mimeType: string, filename: string) {
  const settings = await readSettings();
  if (!settings.encryptedRefreshToken || !settings.folderId) {
    throw new Error("Group-buy receipt storage is not connected. Ask the shop owner to connect Google Drive in Admin Settings.");
  }
  const drive = await getTindahanDriveClient();
  const response = await drive.files.create({
    requestBody: { name: filename, parents: [settings.folderId], mimeType },
    media: { mimeType, body: Readable.from(buffer) },
    fields: "id,webViewLink",
  });
  if (!response.data.id) throw new Error("Google Drive did not return a receipt file ID.");
  return { fileId: response.data.id, webViewLink: response.data.webViewLink ?? "" };
}
