import { timingSafeEqual } from "node:crypto";
import { NextRequest, NextResponse } from "next/server";
import { isTindahanDriveAdmin } from "@/lib/google-drive/admin-auth";
import { createTindahanDriveOAuthClient, saveTindahanDriveRefreshToken, TINDAHAN_DRIVE_FILE_SCOPE } from "@/lib/google-drive/tindahan";

const stateCookie = "tindahan-drive-oauth-state";

function finish(request: NextRequest, status: string) {
  const response = NextResponse.redirect(new URL(`/admin/settings?drive=${status}`, request.url));
  response.cookies.set(stateCookie, "", {
    httpOnly: true,
    secure: request.nextUrl.protocol === "https:",
    sameSite: "lax",
    maxAge: 0,
    path: "/",
  });
  return response;
}

export async function GET(request: NextRequest) {
  const state = request.nextUrl.searchParams.get("state") ?? "";
  const expectedState = request.cookies.get(stateCookie)?.value ?? "";
  const stateMatches = state.length > 0 && state.length === expectedState.length && timingSafeEqual(Buffer.from(state), Buffer.from(expectedState));
  if (!stateMatches) return finish(request, "error");
  if (!(await isTindahanDriveAdmin())) return finish(request, "unauthorized");
  if (request.nextUrl.searchParams.has("error")) return finish(request, "cancelled");

  const code = request.nextUrl.searchParams.get("code");
  if (!code) return finish(request, "error");
  try {
    const callbackUrl = new URL("/api/admin/google-drive/callback", request.url).toString();
    const client = createTindahanDriveOAuthClient(callbackUrl);
    const { tokens } = await client.getToken(code);
    if (tokens.scope && !tokens.scope.split(" ").includes(TINDAHAN_DRIVE_FILE_SCOPE)) {
      throw new Error("Google Drive file access was not granted.");
    }
    if (!tokens.refresh_token) throw new Error("Google did not return offline access.");
    await saveTindahanDriveRefreshToken(tokens.refresh_token);
    return finish(request, "connected");
  } catch (error) {
    console.error("Tindahan Google Drive OAuth callback failed:", error);
    return finish(request, "error");
  }
}
