      const script = document.createElement("script");
      script.src = "https://apis.google.com/js/api.js";
      script.async = true;
      script.dataset.tindahanPicker = "true";
      script.onload = loadPicker;
      script.onerror = () => mounted && setMessage("Google Drive folder picker did not load. Refresh the page and try again.");
      document.head.appendChild(script);
