      <div>
        <h2 className="text-lg font-bold text-[var(--color-text-primary)]">Group-buy receipt folder</h2>
        <p className="mt-1 text-sm text-[var(--color-text-secondary)]">Connect Google Drive, then choose the Tindahan ni Tinapa Group Buy Receipts folder.</p>
