          {connected ? folderName ? `Saving receipts to ${folderName}` : "Drive connected; choose a receipt folder." : "PBC's existing receipt uploads stay unchanged."}
        </span>
      </div>
      {connected && !pickerConfigured && <p className="text-sm text-[var(--color-status-danger)]">Set NEXT_PUBLIC_GOOGLE_PICKER_API_KEY and NEXT_PUBLIC_GOOGLE_PICKER_APP_ID in Vercel to choose a folder.</p>}
      {!oauthConfigured && <p className="text-sm text-[var(--color-status-danger)]">Set GOOGLE_OAUTH_CLIENT_ID and GOOGLE_OAUTH_CLIENT_SECRET in Vercel before connecting.</p>}
      {message && <p role="status" className="text-sm text-[var(--color-text-secondary)]">{message}</p>}
    </section>
  );
}
