+  try {
+    const properties = PropertiesService.getScriptProperties();
+    const expectedSecret = properties.getProperty(PROP_SHARED_SECRET) || "";
+    const payload = JSON.parse(event && event.postData && event.postData.contents || "{}");
+    if (!expectedSecret || !constantTimeEquals_(String(payload.sharedSecret || ""), expectedSecret)) {
+      return json_({ ok: false, error: "Unauthorized." });
+    }
+
+    const folderId = properties.getProperty(PROP_FOLDER_ID);
+    if (!folderId) return json_({ ok: false, error: "Receipt folder setup is incomplete." });
+
+    const mimeType = String(payload.mimeType || "");
+    if (!["image/jpeg", "image/png", "image/webp"].includes(mimeType)) {
+      return json_({ ok: false, error: "Unsupported receipt image type." });
+    }
+
+    const imageBase64 = String(payload.imageBase64 || "");
+    if (!imageBase64 || imageBase64.length > 4200000 || !/^[A-Za-z0-9+/]+={0,2}$/.test(imageBase64)) {
+      return json_({ ok: false, error: "Invalid receipt image data." });
+    }
