// Run once from the Apps Script editor. This creates a private My Drive folder
// and grants the admin-pbc Drive service account access for receipt viewing.
function setupTindahanGroupBuyReceipts() {
  const properties = PropertiesService.getScriptProperties();
  const secret = properties.getProperty(PROP_SHARED_SECRET) || "";
  const readerEmail = properties.getProperty(PROP_READER_EMAIL) || "";
  if (secret.length < 32) throw new Error("Set a random 32-character or longer receipt secret in Script Properties first.");
  if (!/^[^\s@]+@[^\s@]+$/.test(readerEmail)) throw new Error("Set the admin-pbc Drive service account email in Script Properties first.");

  const root = DriveApp.getRootFolder();
  const matches = root.getFoldersByName(RECEIPT_FOLDER_NAME);
  const folder = matches.hasNext() ? matches.next() : root.createFolder(RECEIPT_FOLDER_NAME);
  folder.setSharing(DriveApp.Access.PRIVATE, DriveApp.Permission.NONE);
  folder.addEditor(readerEmail);
  properties.setProperty(PROP_FOLDER_ID, folder.getId());
  Logger.log("GB receipt folder ID: %s", folder.getId());
  return folder.getId();
}

function doPost(event) {
  try {
    const properties = PropertiesService.getScriptProperties();
    const expectedSecret = properties.getProperty(PROP_SHARED_SECRET) || "";
    const payload = JSON.parse(event && event.postData && event.postData.contents || "{}");
    if (!expectedSecret || !constantTimeEquals_(String(payload.sharedSecret || ""), expectedSecret)) {
      return json_({ ok: false, error: "Unauthorized." });
    }

    const folderId = properties.getProperty(PROP_FOLDER_ID);
    if (!folderId) return json_({ ok: false, error: "Receipt folder setup is incomplete." });

    const mimeType = String(payload.mimeType || "");
    if (!["image/jpeg", "image/png", "image/webp"].includes(mimeType)) {
      return json_({ ok: false, error: "Unsupported receipt image type." });
    }

    const imageBase64 = String(payload.imageBase64 || "");
    if (!imageBase64 || imageBase64.length > 4200000 || !/^[A-Za-z0-9+/]+={0,2}$/.test(imageBase64)) {
      return json_({ ok: false, error: "Invalid receipt image data." });
    }

    const bytes = Utilities.base64Decode(imageBase64);
    if (!bytes.length || bytes.length > MAX_RECEIPT_BYTES) {
      return json_({ ok: false, error: "Receipt image must be under 3 MB." });
    }

    const name = String(payload.filename || "receipt").replace(/[^A-Za-z0-9_.-]/g, "_").slice(0, 120) || "receipt";
    const blob = Utilities.newBlob(bytes, mimeType, name);
    const folder = DriveApp.getFolderById(folderId);
    const file = folder.createFile(blob);
    return json_({ ok: true, fileId: file.getId(), folderId: folder.getId() });
  } catch (error) {
    console.error("Group-buy receipt upload failed: %s", error && error.message || error);
    return json_({ ok: false, error: "Receipt upload failed." });
  }
}

function constantTimeEquals_(actual, expected) {
  if (actual.length !== expected.length) return false;
  let difference = 0;
  for (let index = 0; index < actual.length; index += 1) {
    difference |= actual.charCodeAt(index) ^ expected.charCodeAt(index);
  }
  return difference === 0;
}

function json_(value) {
  return ContentService.createTextOutput(JSON.stringify(value))
    .setMimeType(ContentService.MimeType.JSON);
