function parse(s,prefix=""){
 const out=new Map(); let pos=0;
 while(pos<s.length){
  const open=s.indexOf("{",pos); if(open<0) break;
  const sel=s.slice(pos,open).trim();
  let depth=1,j=open+1; for(;j<s.length&&depth;j++){if(s[j]==="{")depth++;else if(s[j]==="}")depth--;}
  const body=s.slice(open+1,j-1);
  if(sel.startsWith("@media")) for(const [k,v] of parse(body,prefix+sel+" ").entries()) out.set(k,v);
  else if(sel.startsWith("@keyframes")||sel.startsWith("@-webkit-keyframes")){}
  else out.set(prefix+sel,body.trim());
  pos=j;
 }
 return out;
}
